// Typed calls to DataLab's API. Types come from the backend's OpenAPI schema
// (schema.d.ts, generated by `npm run api-types`).
import type { components } from "./schema";

type Schemas = components["schemas"];
export type Conversation = Schemas["ConversationOut"];
export type Mode = Schemas["ModeOut"];
export type Models = Schemas["ModelsOut"];
export type QueryRecord = Schemas["QueryRecordOut"];
export type Effort = NonNullable<Schemas["NewMessage"]["effort"]>;
export type SafetyReport = Schemas["SafetyReportOut"];
export type CheckResult = Schemas["CheckResultOut"];
export type WorkspaceFile = Schemas["FileOut"];
export type FileRoot = Schemas["NewPreview"]["root"];
export type Checkpoint = Schemas["CheckpointOut"];
export type RestoreResult = Schemas["RestoreOut"];
export type Attachment = Schemas["AttachmentOut"];
export type AttachResult = Schemas["AttachResult"];
export type Destination = Schemas["DestinationOut"];
export type ExportResult = Schemas["ExportOut"];

export interface Health {
  status: string;
  version: string;
  profile: "real" | "practice";
  database_configured: boolean;
  catalog_tables: number;
}

export class ApiError extends Error {
  constructor(
    readonly status: number,
    message: string,
  ) {
    super(message);
  }
}

/** Fired when DataLab no longer knows this browser (it restarted, or the sign-in expired). */
export const SIGNED_OUT = "datalab:signed-out";

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(path, {
    ...init,
    headers: { "content-type": "application/json", ...init?.headers },
  });
  if (!response.ok) {
    if (response.status === 401) window.dispatchEvent(new Event(SIGNED_OUT));
    const body = await response.json().catch(() => ({}));
    const detail = typeof body.detail === "string" ? body.detail : response.statusText;
    throw new ApiError(response.status, detail);
  }
  return response.status === 204 ? (undefined as T) : response.json();
}

export const api = {
  health: () => request<Health>("/api/health"),
  modes: () => request<Mode[]>("/api/modes"),
  models: () => request<Models>("/api/models"),
  conversations: () => request<Conversation[]>("/api/conversations"),
  conversation: (id: string) => request<Conversation>(`/api/conversations/${id}`),
  // No title: DataLab writes one from the first question.
  createConversation: (mode: string, model?: string) =>
    request<Conversation>("/api/conversations", {
      method: "POST",
      body: JSON.stringify({ mode, model }),
    }),
  rename: (id: string, title: string) =>
    request<Conversation>(`/api/conversations/${id}`, { method: "PATCH", body: JSON.stringify({ title }) }),
  deleteConversation: (id: string) =>
    request<void>(`/api/conversations/${id}`, { method: "DELETE" }),
  send: (id: string, text: string, effort?: Effort) =>
    request<Conversation>(`/api/conversations/${id}/messages`, {
      method: "POST",
      body: JSON.stringify({ text, effort }),
    }),
  answerApproval: (id: string, approvalId: string, approve: boolean, question: string, plan?: Record<string, string>) =>
    request<void>(`/api/conversations/${id}/approvals/${approvalId}`, {
      method: "POST",
      body: JSON.stringify({ approve, question, plan }),
    }),
  setRigorReview: (id: string, on: boolean) =>
    request<Conversation>(`/api/conversations/${id}`, { method: "PATCH", body: JSON.stringify({ rigor_review: on }) }),
  stop: (id: string) => request<Conversation>(`/api/conversations/${id}/stop`, { method: "POST" }),
  dataAccessed: (id: string) => request<QueryRecord[]>(`/api/conversations/${id}/data-accessed`),
  files: (id: string, root: FileRoot = "outputs") =>
    request<WorkspaceFile[]>(`/api/conversations/${id}/files?root=${root}`),
  /** Where the viewer loads a file from (images are shown straight from this), as of one checkpoint. */
  fileUrl: (id: string, root: FileRoot, path: string, checkpoint?: number | null) =>
    `/api/conversations/${id}/files/${root}/${path.split("/").map(encodeURIComponent).join("/")}` +
    (checkpoint != null ? `?checkpoint=${checkpoint}` : ""),
  fileText: async (id: string, root: FileRoot, path: string, checkpoint?: number | null) => {
    const response = await fetch(api.fileUrl(id, root, path, checkpoint));
    if (!response.ok) throw new ApiError(response.status, "This file can't be shown.");
    return { text: await response.text(), truncated: response.headers.get("x-datalab-truncated") === "1" };
  },
  preview: (id: string, root: FileRoot, path: string, checkpoint?: number | null) =>
    request<{ url: string; checkpoint: number }>(`/api/conversations/${id}/previews`, {
      method: "POST",
      body: JSON.stringify({ root, path, checkpoint: checkpoint ?? null }),
    }),
  checkpoints: (id: string) => request<Checkpoint[]>(`/api/conversations/${id}/checkpoints`),
  restore: (id: string, number: number) =>
    request<RestoreResult>(`/api/conversations/${id}/checkpoints/${number}/restore`, { method: "POST" }),
  inputs: (id: string) => request<Attachment[]>(`/api/conversations/${id}/inputs`),
  inputSamples: () => request<string[]>("/api/input-samples"),
  attach: (id: string, source: "files" | "folder" | "sample", sample?: string) =>
    request<AttachResult>(`/api/conversations/${id}/inputs`, {
      method: "POST",
      body: JSON.stringify({ source, sample }),
    }),
  detach: (id: string, attachmentId: string) =>
    request<void>(`/api/conversations/${id}/inputs/${attachmentId}`, { method: "DELETE" }),
  /** Every event in a conversation (the API returns them 1,000 at a time). */
  allEvents: async (id: string) => {
    const all: { seq: number; type: string; data: Record<string, unknown> }[] = [];
    for (;;) {
      const page = await request<{ seq: number; type: string; data: Record<string, unknown> }[]>(
        `/api/conversations/${id}/events?after=${all.at(-1)?.seq ?? 0}`,
      );
      all.push(...page);
      if (page.length < 1000) return all;
    }
  },
  destinations: () => request<Destination[]>("/api/export-destinations"),
  addDestination: () => request<Destination>("/api/export-destinations", { method: "POST" }),
  removeDestination: (id: string) => request<void>(`/api/export-destinations/${id}`, { method: "DELETE" }),
  export: (
    id: string,
    destinationId: string,
    files: { root: FileRoot; path: string }[],
    report?: { html: string; css: string },
    checkpoint?: number,
    rawHtml = false,
  ) =>
    request<ExportResult>(`/api/conversations/${id}/exports`, {
      method: "POST",
      body: JSON.stringify({ destination_id: destinationId, files, report, checkpoint, raw_html: rawHtml }),
    }),
  lastSafetyReport: () => request<SafetyReport | null>("/api/safety/last"),
  runSafetyCheck: () => request<SafetyReport>("/api/safety/check", { method: "POST" }),
};
